    "id": "tb_ielts_089",
    "title": "Công Thái Học Nơi Làm Việc Và Sức Khỏe Cơ Xương Khớp",
    "titleEn": "Workplace Ergonomics and Musculoskeletal Health",
    "sourceGroup": "ielts_reading",
