    "title": "Nông Điện Kết Hợp: Canh Tác Dưới Tán Pin Mặt Trời",
    "titleEn": "Agrivoltaic Dual-Use Solar Farming",
    "sourceGroup": "ielts_reading",
    "sourceLabel": "IELTS Reading",
    "unitId": null,
    "unitNumber": null,
